import java.text.SimpleDateFormat
import java.util.Date
import java.security.MessageDigest
import java.math.BigInteger

try {
    // ========== 1. DATA CLEANING ==========

    // Trim all string fields
    def textFields = ['event_id', 'airline', 'flight_number', 'aircraft_model', 'aircraft_type',
                     'origin', 'destination', 'city', 'country', 'cause', 'damage']

    textFields.each { fieldName ->
        def value = record.getValue(fieldName)
        if (value != null) {
            record.setValue(fieldName, value.toString().trim())
        }
    }

    // Damage field - uppercase
    def damage = record.getValue('damage')
    if (damage != null) {
        record.setValue('damage', damage.toString().toUpperCase())
    }    // city field - uppercase
    def city = record.getValue('city')
    if (city != null) {
        record.setValue('city', city.toString().toUpperCase())
    }    // airline field - uppercase
    def airline = record.getValue('airline')
    if (airline != null) {
        record.setValue('airline', airline.toString().toUpperCase())
    }    // country field - uppercase
    def country = record.getValue('country')
    if (country != null) {
        record.setValue('country', country.toString().toUpperCase())
    }

    // Flight number - standardize format
    def flightNum = record.getValue('flight_number')
    if (flightNum != null) {
        def cleanFlight = flightNum.toString().toUpperCase()
        cleanFlight = cleanFlight.replaceAll('[^A-Z0-9\\-]', '')
        record.setValue('flight_number', cleanFlight)
    }

    // ========== 2. DUPLICATE DETECTION HASH ==========
    def eventId = record.getValue('event_id')
    if (eventId != null) {
        // Create a hash of key fields for duplicate detection
        def duplicateKey = [
            eventId.toString(),
            record.getValue('flight_number') ?: '',
            record.getValue('timestamp') ?: ''
        ].collect { it.toString() }.join('|')

        // Create MD5 hash
        def md5 = MessageDigest.getInstance("MD5")
        md5.update(duplicateKey.getBytes())
        def hash = new BigInteger(1, md5.digest()).toString(16).padLeft(32, '0')
        record.setValue('_record_hash', hash)
    }

    // ========== 5. VALIDATION ==========

    def isValid = true
    def validationErrors = []

    // Required fields
    if (!record.getValue('event_id') || record.getValue('event_id').toString().isEmpty()) {
        validationErrors.add("MISSING_EVENT_ID")
        isValid = false
    }

    // Return the transformed record
    return record

} catch (Exception e) {
    log.error("Transformation failed: " + e.getMessage(), e)

    // Add error info but still return record
    record.setValue('_transformation_error', e.getMessage())
    record.setValue('_transformation_status', 'FAILED')

    return record
}

def flowFile = session.get()
if (flowFile != null) {
    // Get latitude and longitude attributes
    def latVal = flowFile.getAttribute("latitude")
    def lonVal = flowFile.getAttribute("longitude")

    // ========== 1. CONVERT TO INTEGERS ==========
    def latInt = "0"
    def lonInt = "0"

    // Process latitude
    if (latVal != null) {
        try {
            // Convert to integer (rounds to nearest integer)
            latInt = Math.round(latVal.toFloat()).toString()
            flowFile = session.putAttribute(flowFile, "latitude_int", latInt)
        } catch (Exception e) {
            // If conversion fails, set to 0
            flowFile = session.putAttribute(flowFile, "latitude_int", "0")
        }
    } else {
        // If attribute is missing, set to 0
        flowFile = session.putAttribute(flowFile, "latitude_int", "0")
    }

    // Process longitude
    if (lonVal != null) {
        try {
            // Convert to integer (rounds to nearest integer)
            lonInt = Math.round(lonVal.toFloat()).toString()
            flowFile = session.putAttribute(flowFile, "longitude_int", lonInt)
        } catch (Exception e) {
            // If conversion fails, set to 0
            flowFile = session.putAttribute(flowFile, "longitude_int", "0")
        }
    } else {
        // If attribute is missing, set to 0
        flowFile = session.putAttribute(flowFile, "longitude_int", "0")
    }

    // ========== 2. ADD NEW ATTRIBUTES ==========

    // Combined coordinate string
    flowFile = session.putAttribute(flowFile, "coords_int", "${latInt},${lonInt}")

    // Hemisphere detection
    def hemisphere = "Unknown"
    try {
        def latFloat = latVal?.toFloat() ?: 0
        def lonFloat = lonVal?.toFloat() ?: 0

        if (latFloat > 0 && lonFloat > 0) {
            hemisphere = "NE_Quadrant"
        } else if (latFloat > 0 && lonFloat < 0) {
            hemisphere = "NW_Quadrant"
        } else if (latFloat < 0 && lonFloat > 0) {
            hemisphere = "SE_Quadrant"
        } else if (latFloat < 0 && lonFloat < 0) {
            hemisphere = "SW_Quadrant"
        } else if (latFloat == 0 && lonFloat == 0) {
            hemisphere = "Null_Island"
        } else if (latFloat == 0) {
            hemisphere = "Equator"
        } else if (lonFloat == 0) {
            hemisphere = "Prime_Meridian"
        }
    } catch (Exception e) {
        hemisphere = "Invalid"
    }
    flowFile = session.putAttribute(flowFile, "hemisphere", hemisphere)

    // Coordinate validity check
    def isValidCoords = "true"
    try {
        def lat = latVal?.toFloat() ?: 0
        def lon = lonVal?.toFloat() ?: 0

        if (lat < -90 || lat > 90 || lon < -180 || lon > 180) {
            isValidCoords = "false"
        }
    } catch (Exception e) {
        isValidCoords = "false"
    }
    flowFile = session.putAttribute(flowFile, "coords_valid", isValidCoords)

    // Distance from origin (0,0) - simplified
    try {
        def lat = latVal?.toFloat() ?: 0
        def lon = lonVal?.toFloat() ?: 0
        def distance = Math.sqrt(lat*lat + lon*lon)
        flowFile = session.putAttribute(flowFile, "distance_from_origin", String.format("%.2f", distance))
    } catch (Exception e) {
        flowFile = session.putAttribute(flowFile, "distance_from_origin", "0.00")
    }

    // ========== 3. DATA CLEANING ATTRIBUTES ==========

    // Data quality score (simple)
    def qualityScore = 100

    // Deduct for missing coordinates
    if (latVal == null || lonVal == null) {
        qualityScore -= 50
    }

    // Deduct for invalid coordinates
    if (isValidCoords == "false") {
        qualityScore -= 30
    }

    // Deduct for zero coordinates (suspicious data)
    try {
        if ((latVal?.toFloat() ?: 0) == 0 && (lonVal?.toFloat() ?: 0) == 0) {
            qualityScore -= 20
        }
    } catch (Exception e) {
        // Ignore
    }

    qualityScore = Math.max(0, qualityScore)
    flowFile = session.putAttribute(flowFile, "data_quality_score", qualityScore.toString())

    // Data source tracking
    flowFile = session.putAttribute(flowFile, "data_source", "airplane_crashes_raw")
    flowFile = session.putAttribute(flowFile, "processing_timestamp", System.currentTimeMillis().toString())
    flowFile = session.putAttribute(flowFile, "processing_stage", "coordinate_processing")

    session.transfer(flowFile, REL_SUCCESS)
}
